package com.bank.risk.service;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Longest continuous stretch with equal wins (1) and losses (0).
public class BreakEvenAnalyzer {
    private static final Logger log = Logger.getLogger(BreakEvenAnalyzer.class.getName());

    public int longestBreakEvenRun(int[] outcomes) {
        if (outcomes == null || outcomes.length == 0) {
            return 0;
        }
        Map<Integer, Integer> firstIndex = new HashMap<>();
        firstIndex.put(0, -1); // empty prefix before the array
        int prefix = 0;
        int best = 0;

        for (int i = 0; i < outcomes.length; i++) {
            prefix += (outcomes[i] == 1) ? 1 : -1; // 0 → -1, 1 → +1
            Integer seenAt = firstIndex.get(prefix);
            if (seenAt != null) {
                int len = i - seenAt;
                if (len > best) {
                    best = len;
                    final int b = best, s = seenAt + 1, e = i;
                    log.fine(() -> "Balanced run [" + s + ".." + e + "] length " + b);
                }
            } else {
                firstIndex.put(prefix, i); // store FIRST occurrence only
            }
        }
        final int result = best;
        log.info(() -> "Longest break-even run over " + Arrays.toString(outcomes)
                + " = " + result);
        return best;
    }
}
